from collections import defaultdict, deque

def bfs_shortest_path(graph, start):
    n = len(graph)
    dist = [-1] * n
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def lca_query(u, v, parent, depth, dp):
    if depth[u] > depth[v]:
        u, v = v, u
    diff = depth[v] - depth[u]
    for i in range(18, -1, -1):
        if diff & (1 << i):
            v = dp[v][i]
    if u != v:
        for i in range(17, -1, -1):
            if dp[u][i] != dp[v][i]:
                u = dp[u][i]
                v = dp[v][i]
        u = dp[u][0]
    return u

